def url(i):
    u,t,c = POSTS[i]
    return f"https://www.instagram.com/{u}/{t}/{c}/"

# Spots: (name, geocode query or (lat,lon), district, category, [post idx], note)
# Categories: Aussicht, Neon, Architektur, Street, Markt, Tram, Dorf, Food
